INSERT INTO `ezcontentobject_attribute` VALUES (0,353,191,0,1045487555,'<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph>What kind of diet is best for maintaining the health of aging brains and bodies? A common answer these days is the “Mediterranean diet,” due to a combination of recently published research studies and frequent media coverage.</paragraph></section>','ezxmltext',2353,'eng-GB',2,0,'',1);
