INSERT INTO `ezcontentobject_attribute` VALUES (0,769,207,0,NULL,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<ezimage serial_number=\"1\" is_valid=\"1\" filename=\"recipe-test.jpg\" suffix=\"jpg\" basename=\"recipe-test\" dirpath=\"var/site/storage/images/www-home/showcase/recipe-test/2489-1-eng-GB\" url=\"var/site/storage/images/www-home/showcase/recipe-test/2489-1-eng-GB/recipe-test.jpg\" original_filename=\"c9111d50.jpg\" mime_type=\"image/jpeg\" width=\"607\" height=\"400\" alternative_text=\"Zucchini Zoodles with Ground Turkey Tomato Sauce\" alias_key=\"1293033771\" timestamp=\"1575010775\"><original attribute_id=\"2489\" attribute_version=\"1\" attribute_language=\"eng-GB\"/><information Height=\"400\" Width=\"607\" IsColor=\"1\"/><alias name=\"small\" filename=\"recipe-test_small.jpg\" suffix=\"jpg\" dirpath=\"var/site/storage/images/www-home/showcase/recipe-test/2489-1-eng-GB\" url=\"var/site/storage/images/www-home/showcase/recipe-test/2489-1-eng-GB/recipe-test_small.jpg\" mime_type=\"image/jpeg\" width=\"100\" height=\"66\" alias_key=\"1455834182\" timestamp=\"1747047563\" is_valid=\"1\"/></ezimage>\n','ezimage',2489,'eng-GB',2,0,'',1);
