INSERT INTO `ezcontentobject_attribute` VALUES (0,771,207,0,1045487555,'<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph>This easy recipe only takes about 10 minutes to make – start to finish – and it\'s both delicious and nutritious.</paragraph></section>','ezxmltext',2491,'eng-GB',2,0,'',1);
INSERT INTO `ezcontentobject_attribute` VALUES (0,772,207,0,1045487555,'<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"/>','ezxmltext',2492,'eng-GB',2,0,'',1);
INSERT INTO `ezcontentobject_attribute` VALUES (0,773,207,0,1045487555,'<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph><emphasize>Serves 4</emphasize></paragraph><paragraph>Note: if you are not following a low FODMAP diet, feel free to add onions and garlic to this recipe for added flavor.</paragraph><section><section><header>INGREDIENTS</header><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><ul><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">1 package ground turkey (about 1+ lb)</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Olive oil</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">1 14-ounce can organic fire roasted tomatoes</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Salt and pepper, to taste</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Seasoning of your choice, such as a dried Italian herb mix, to taste</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">4 medium zucchini, spiralized</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">For garnish, freshly grated Parmesan cheese and a drizzle of *basil olive oil (*see note below)</paragraph></li></ul></paragraph></section></section><section><section><header>PREPARATION</header><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><ol><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Add a drizzle or two of olive oil to a large and heat on medium-high (other oils that are wonderful drizzled over to finish this dish are truffle oil, lemon oil, or any non-flavored high-quality olive oil). Add ground turkey and cook, breaking up the meat with a spatula, until browned, about 3 to 4 minutes. Season to taste with salt, pepper, and Italian herbs. Transfer to a serving bowl and set aside.</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Add a bit more olive oil to the skillet (if necessary) and toss in the zucchini zoodles. Cook, tossing frequently, until softened, about 3-5 minutes depending on how cooked you\'d like them (I like them still a bit tender, which is a cook time of about 3 minutes).  Transfer to the serving bowl and gently toss with the tomato meat sauce.</paragraph></li><li><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Plate and top each serving with freshly grated Parmesan cheese and a drizzle of oil.</paragraph></li></ol></paragraph><paragraph><emphasize>Recipe credit: <link target=\"_self\" url_id=\"36\">Sheri Wetherell</link> via <link target=\"_self\" url_id=\"37\">Foodista</link> / <link target=\"_self\" url_id=\"38\">CC BY</link></emphasize></paragraph><paragraph><emphasize><emphasize>Photo credit: <emphasize><link target=\"_self\" url_id=\"37\">Foodista</link> / <link target=\"_self\" url_id=\"38\">CC BY</link></emphasize></emphasize></emphasize></paragraph></section></section></section>','ezxmltext',2493,'eng-GB',2,0,'',1);
