INSERT INTO `ezcontentobject_attribute` VALUES (0,355,741,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph><strong>Redaktion und verantwortlich für den Inhalt der Webseiten:</strong></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">JAC Example</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Straße 1234</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">18439 Stralsund</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Web: www.jac-systeme.de</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">E-Mail: <link target=\"_self\" url_id=\"162\">info@jac-systeme.de</link></line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Tel.: +49 (03 831) 30 65 07</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Fax: +49 (03 831) 70 38 19</line></paragraph><paragraph>Geschäftsführer:  xxx</paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">HRB: Amtsgericht xxx</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Ust.-ID-Nr.: DE xxx xxx xxx</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Urheberrecht und Gewährleistung:</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Alle Angaben auf der Website wurden von der Redaktion nach bestem Wissen erstellt und sorgfältig überprüft. Dennoch sind inhaltliche Fehler nicht vollständig auszuschliessen. Deshalb werden alle Angaben ohne jegliche Gewähr seitens des Herausgebers gemacht. Es kann keinerlei Haftung oder Verantwortung für inhaltliche Fehler, Satzfehler, Auslassungen, Preisangaben usw. übernommen werden. Alle Rechte bleiben vorbehalten. Es ist keine Vervielfältigung, weitere Verbreitung oder Nutzung für kommerzielle Zwecke erlaubt. Ausgenommen davon sind Mitteilungen, Informationen sowie Fotos, welche zu Download angeboten werden. Für letztere gelten gesonderte Nutzungsbedingungen.</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Alle Angebote sind freibleibend und unverbindlich. Der Autor behält es sich ausdrücklich vor, Teile der Seiten oder das gesamte Angebot ohne gesonderte Ankündigung zu verändern, zu ergänzen, zu löschen oder die Veröffentlichung zeitweise oder endgültig einzustellen.</line></paragraph><paragraph>Bei Beschwerden im Zusammenhang mit der Versicherungsvermittlung können Sie sich an den Versicherungsombudsmann e.V. (Schlichtungsstelle) wenden:</paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Versicherungsombudsmann e.V.</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Postfach 080632, 10006 Berlin</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Telefon: 0800 3696000</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Fax: 0800 3699000</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Email: beschwerde@versicherungsombudsmann.de</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">URL: www.versicherungsombudsmann.de</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Haftung</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Wir distanzieren uns hiermit ausdrücklich von den Inhalten aller gelinkten Seiten auf unseren Webseiten.</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Verlinkung</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Eine Verlinkung auf die Homepage www.jac-systeme.de ist ohne Rückfrage statthaft und grundsätzlich erwünscht. Darüber hinaus dürfen Links nur derart gesetzt werden, dass die Navigationsstruktur unserer Seite vollständig erhalten bleibt.</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Fotos</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">©ars-campus, Axel Thiessenhusen, ©Tourismusverband Mecklenburg-Vorpommern, ©Tourismusverband Fischland-Darss-Zingst, ©Kur- und Tourist GmbH Darß, ©Sebastian Semmler, Wieck ©friedrichhillenbrand-pixelio, ©Elke Erdmann, Born ©Wilfried Fischer,Wieck, ©Heike Zehrfeld, Born ©Lutz Storm, Ahrenshoop ©Sten Britt, ©Annett Storm, ©Norbert Rosing, ©Jens Vogt</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Design und technische Umsetzung: </strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">ars-campus, Rostock: <link url_id=\"72\">www.ars-campus.de</link> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">JAC Systeme GmbH: <link target=\"_blank\" url_id=\"73\">www.jac-systeme.de</link></line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Content-Management-System:</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">eZ Publish: <link target=\"_blank\" url_id=\"161\">www.ibexa.co/de</link></line></paragraph></section>\n','ezxmltext',6753,'ger-DE',4,0,'',8);
INSERT INTO `ezcontentobject_attribute` VALUES (0,355,741,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph><strong>Redaktion und verantwortlich für den Inhalt der Webseiten:</strong></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">JAC Example</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Straße 1234</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">18439 Stralsund</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Web: www.jac-systeme.de</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">E-Mail: <link target=\"_self\" url_id=\"162\">info@jac-systeme.de</link></line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Tel.: +49 (03 831) 30 65 07</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Fax: +49 (03 831) 70 38 19</line></paragraph><paragraph>Geschäftsführer:  xxx</paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">HRB: Amtsgericht xxx</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Ust.-ID-Nr.: DE xxx xxx xxx</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Urheberrecht und Gewährleistung:</strong></line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Alle Angaben auf der Website wurden von der Redaktion nach bestem Wissen erstellt und sorgfältig überprüft. Dennoch sind inhaltliche Fehler nicht vollständig auszuschliessen. Deshalb werden alle Angaben ohne jegliche Gewähr seitens des Herausgebers gemacht. Es kann keinerlei Haftung oder Verantwortung für inhaltliche Fehler, Satzfehler, Auslassungen, Preisangaben usw. überno