INSERT INTO `ezcontentobject_attribute` VALUES (0,844,173,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph>Damit diese Website einwandfrei funktioniert und um Ihre Erfahrungen zu verbessern, verwenden wir Cookies. Für detailierte Informationen, besuchen Sie unsere <link node_id=\"809\">Datenschutzseite</link>.</paragraph></section>\n','ezxmltext',10718,'ger-DE',4,0,'',5);
