INSERT INTO `ezcontentobject_attribute` VALUES (0,368,1397,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><paragraph>In Gunter Böhnkes neuem Programm \"Knapp an der Wahrheit vorbei\" wird es, wie der Untertitel \"Märchen haben kurze Beine\" nahelegt, um Märchen und um Lügen gehen sowie um die Frage, ob möglicherweise eine Verbindung zwischen beiden Gattungen besteht.</paragraph></section>\n','ezxmltext',14125,'ger-DE',4,0,'',1);
