INSERT INTO `ezcontentobject_attribute` VALUES (0,368,1398,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><section><header align=\"left\">In seinem Soloprogramm erinnert er sich an seine \"Musikalischen und Zwischenmenschlichen Lehrjahre\" bei den Gruppen \"Handarbeit\" &amp; \"Keimzeit\" und zieht eine: \"musikalische &amp; lebensnahe Zwischenbilanz\".</header></section></section>\n','ezxmltext',14147,'ger-DE',4,0,'',1);
INSERT INTO `ezcontentobject_attribute` VALUES (0,368,1398,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><section><header align=\"left\">In seinem Soloprogramm erinnert er sich an seine \"Musikalischen und Zwischenmenschlichen Lehrjahre\" bei den Gruppen \"Handarbeit\" &amp; \"Keimzeit\" und zieht eine: \"musikalische &amp; lebensnahe Zwischenbilanz\".</header></section></section>\n','ezxmltext',14147,'ger-DE',4,0,'',2);
INSERT INTO `ezcontentobject_attribute` VALUES (0,370,1398,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><section><header align=\"left\">Er singt, spielt Gitarre &amp; Mundharmonika und interpretiert hier eher unveröffentlichte oder: \"vergessene Leisegangsche Lieder\" und natürlich auch: \"Hübnersche Blues\" – gilt er doch als: „…einer der wenigen wirklichen Bluessänger Deutschlands…“ (Zitat: Blues-News-Magazin) Hübner war und ist ein Freigeist, ein Verfechter von Freiheit, Gleichheit und Selbstbestimmung. 1965 im Ostseebad Kühlungsborn geboren, aufgewachsen und sozialisiert in der ehemaligen Deutschen „Diktatorischen“ Republik, lernte er schnell die Grenzen der Möglichkeiten für ein selbstbestimmtes und freiheitliches Leben kennen und geriet in stetigen Konflikt mit dem herrschenden Regime. Rückblickend stellt er heute fest: „…ich habe es überlebt und ich bin dankbar für alle Erfahrungen aus dieser Zeit…“.</header></section><section><header align=\"left\">Seine Konzerte sind intensiv, emotional, berührend, mitreißend und: auch immer mit einem Quäntchen Selbstironie und Humor versehen. Es sind Geschichten aus dem Leben für das Leben, mit allem was dazugehört.</header><paragraph><strong>Datum/Uhrzeit:</strong></paragraph><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><table width=\"40%\"><tr><td><paragraph>Mittwoch, 23. Juni 2021</paragraph></td><td><paragraph>20:00 Uhr*</paragraph></td></tr></table></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Veranstaltungsort:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Darßer Arche</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Kategorie:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Konzert</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Preise:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">ohne Kurkarte: 14,50 EURO </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">für Kurkarteninhaber: 12,00 EURO</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kinder: 5,00 EURO</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Reservierung &amp; Anmeldung:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kurverwaltung Wieck und Kurverwaltung Born</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Ausrichter der Veranstaltung</strong> und inhaltlich Verantwortlicher der hier wiedergegebenen Veranstaltungsinformationen:</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kur und Tourist GmbH Darß</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Bliesenraderweg 2</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">18375 Wieck a. Darß</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Tel: 038233 - 201</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">E-Mail: wieck@darss.org</line></paragraph><paragraph><custom name=\"sub\">*Die Veranstaltung findet unter Corona - Schutzbestimmungen statt, d.h., die Teilnehmer geben zu Beginn ihre Kontaktdaten bekannt, halten erforderlichen Abstand und führen einen Mundschutz für gegebene Situationen mit.</custom></paragraph></section></section>\n','ezxmltext',14148,'ger-DE',4,0,'',1);
INSERT INTO `ezcontentobject_attribute` VALUES (0,370,1398,0,1045487555,'<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<section xmlns:image=\"http://ez.no/namespaces/ezpublish3/image/\" xmlns:xhtml=\"http://ez.no/namespaces/ezpublish3/xhtml/\" xmlns:custom=\"http://ez.no/namespaces/ezpublish3/custom/\"><section><header align=\"left\">Er singt, spielt Gitarre &amp; Mundharmonika und interpretiert hier eher unveröffentlichte oder: \"vergessene Leisegangsche Lieder\" und natürlich auch: \"Hübnersche Blues\" – gilt er doch als: „…einer der wenigen wirklichen Bluessänger Deutschlands…“ (Zitat: Blues-News-Magazin) Hübner war und ist ein Freigeist, ein Verfechter von Freiheit, Gleichheit und Selbstbestimmung. 1965 im Ostseebad Kühlungsborn geboren, aufgewachsen und sozialisiert in der ehemaligen Deutschen „Diktatorischen“ Republik, lernte er schnell die Grenzen der Möglichkeiten für ein selbstbestimmtes und freiheitliches Leben kennen und geriet in stetigen Konflikt mit dem herrschenden Regime. Rückblickend stellt er heute fest: „…ich habe es überlebt und ich bin dankbar für alle Erfahrungen aus dieser Zeit…“.</header></section><section><header align=\"left\">Seine Konzerte sind intensiv, emotional, berührend, mitreißend und: auch immer mit einem Quäntchen Selbstironie und Humor versehen. Es sind Geschichten aus dem Leben für das Leben, mit allem was dazugehört.</header><paragraph><strong>Datum/Uhrzeit:</strong></paragraph><paragraph xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><table class=\"table-striped\" border=\"0\" width=\"40%\" custom:caption=\"\"><tr><td><paragraph>Mittwoch, 23. Juni 2021</paragraph></td><td><paragraph>20:00 Uhr*</paragraph></td></tr></table></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Veranstaltungsort:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Darßer Arche</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Kategorie:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Konzert</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Preise:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">ohne Kurkarte: 14,50 EURO </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">für Kurkarteninhaber: 12,00 EURO</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kinder: 5,00 EURO</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Reservierung &amp; Anmeldung:</strong> </line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kurverwaltung Wieck und Kurverwaltung Born</line></paragraph><paragraph><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\"><strong>Ausrichter der Veranstaltung</strong> und inhaltlich Verantwortlicher der hier wiedergegebenen Veranstaltungsinformationen:</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Kur und Tourist GmbH Darß</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Bliesenraderweg 2</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">18375 Wieck a. Darß</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">Tel: 038233 - 201</line><line xmlns:tmp=\"http://ez.no/namespaces/ezpublish3/temporary/\">E-Mail: wieck@darss.org</line></paragraph><paragraph><custom name=\"sub\">*Die Veranstaltung findet unter Corona - Schutzbestimmungen statt, d.h., die Teilnehmer geben zu Beginn ihre Kontaktdaten bekannt, halten erforderlichen Abstand und führen einen Mundschutz für gegebene Situationen mit.</custom></paragraph></section></section>\n','ezxmltext',14148,'ger-DE',4,0,'',2);
